import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Carpentry","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/carpentry.md","filePath":"en/guide/professions/carpentry.md"}'),n={name:"en/guide/professions/carpentry.md"};function o(s,e,l,d,h,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="carpentry" tabindex="-1">Carpentry <a class="header-anchor" href="#carpentry" aria-label="Permalink to &quot;Carpentry&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Turn wood knowledge into equipment, construction and field structures.</li><li>Preparation, grain and joinery should matter without simulating every cut.</li><li>Bowmaking is a learned <a href="/Syrolands-Public/en/guide/characters/techniques.html">technique</a> path, not an automatic Carpentry reward.</li></ul><p><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Activity</th><th>What you do</th></tr></thead><tbody><tr><td>Work the wood</td><td>Season, select, cut, shape, join, assemble and finish.</td></tr><tr><td>Make useful structures</td><td>Furniture, containers, handles, shields, camp structures and mine supports are candidate outputs.</td></tr><tr><td>Learn</td><td>Build a Woodworker’s Journal through teachers, manuscripts, challenges and exploration.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Carpentry already makes furniture and workshop structures, sometimes using other skills.</td><td>Material preparation and construction choices deepen that role in expeditions.</td></tr><tr><td>Bowcraft and Fletching is a separate UO skill.</td><td>Bowmaking is proposed as a learned Carpentry/Archery path.</td></tr></tbody></table><p>Comparison uses familiar UO crafting loops; the official references also cover later expansions. <a href="https://uo.com/wiki/ultima-online-wiki/skills/carpentry/" target="_blank" rel="noreferrer">Carpentry</a> · <a href="https://uo.com/wiki/ultima-online-wiki/skills/bowcraft-and-fletching/" target="_blank" rel="noreferrer">Bowcraft And Fletching</a>.</p><h2 id="bowmaking-and-fletching" tabindex="-1">Bowmaking and Fletching <a class="header-anchor" href="#bowmaking-and-fletching" aria-label="Permalink to &quot;Bowmaking and Fletching&quot;">​</a></h2><p>Learn the path through Carpentry and Archery, with optional Tailoring and Blacksmithing support. Season and shape the stave, tiller, string, tune and test the bow. Arrows combine shafts, heads, fletching and assembly; their exact roles remain open. A Master Bowyer identity should take sustained knowledge and practice.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>An archer learns Bowmaking from a teacher, then practices selecting a stave, tillering and tuning it. Ordinary Carpentry alone would not grant that knowledge.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><ul><li>Camping, Mining, Tinkering and Blacksmithing can contribute to structures and composite items. Placement and protection rules remain open.</li><li>Luthiery and ship components remain possible future paths. Existing Bowcraft characters still need an explicit transition policy.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/professions/lumberjacking.html">Lumberjacking</a> · <a href="/Syrolands-Public/en/guide/professions/mining.html">Mining</a> · <a href="/Syrolands-Public/en/guide/professions/tinkering.html">Tinkering</a> · <a href="/Syrolands-Public/en/guide/items/item-quality.html">Item Quality</a> · <a href="/Syrolands-Public/en/guide/professions/overview.html">Profession System</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/professions/carpentry.html">Carpentry</a></p>',20)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
